            out.append(f"#delimiter: {names[self.delimiter]}")
        if self.decimal is not None:
            out.append(f"#decimal: {self.decimal}")
        if len(self.date_orders) == 1:
            out.append(f"#date_order: {self.date_orders[0]}")
